import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.CLyRW9b_.js";const m=JSON.parse('{"title":"Mockups are plain HTML in the repo","description":"","frontmatter":{"status":"accepted","date":"2026-10-26T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0016-mockups-are-plain-html-in-the-repo.md","filePath":"docs/adr/0016-mockups-are-plain-html-in-the-repo.md"}'),o={name:"docs/adr/0016-mockups-are-plain-html-in-the-repo.md"};function r(i,e,d,c,l,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="mockups-are-plain-html-in-the-repo" tabindex="-1">Mockups are plain HTML in the repo <a class="header-anchor" href="#mockups-are-plain-html-in-the-repo" aria-label="Permalink to &quot;Mockups are plain HTML in the repo&quot;">​</a></h1><p>Screen mockups live in <code>design/mockups/</code> as plain HTML pages, styled only with the generated token CSS and Poulpy drawings, and change through PRs like the code. The docs site shows them, and a CI check keeps them on the tokens, the way ADR 0012 keeps the themes and drawings on <code>design/tokens.json</code>. The claude.ai Design canvas that held them until now only renders with claude.ai&#39;s own runtime and loads its images from claude.ai, so it cannot be reviewed in a PR or shown on the site; it stays a scratch space for rough ideas, never the record. The research behind this is in <a href="./../research/mockups-source-of-truth"><code>docs/research/mockups-source-of-truth.md</code></a>.</p><h2 id="how-the-folder-is-organised" tabindex="-1">How the folder is organised <a class="header-anchor" href="#how-the-folder-is-organised" aria-label="Permalink to &quot;How the folder is organised&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>design/mockups/</span></span>
<span class="line"><span>  shared/                  mockup.css (the device frames and common components), shared images</span></span>
<span class="line"><span>  drafts/phone/            screens being explored or redesigned</span></span>
<span class="line"><span>  drafts/tablet/</span></span>
<span class="line"><span>  drafts/web/</span></span>
<span class="line"><span>  agreed/phone/            screens the owner validated; what the apps are built from</span></span>
<span class="line"><span>  agreed/tablet/</span></span>
<span class="line"><span>  agreed/web/</span></span></code></pre></div><ul><li><strong>Drafts are kept apart from validated mockups.</strong> A new screen or a redesign starts in <code>drafts/</code>. Validating it is a PR that moves it to <code>agreed/</code>, replacing the old version there, and the owner&#39;s merge is the approval. Nothing is built from a draft.</li><li><strong>One folder per form factor.</strong> Phone, tablet and website screens each get their own folder and device frame. A screen keeps the same file name in every folder (<code>home-planned.html</code>), so its phone, tablet and web versions, and its draft and agreed versions, are easy to pair.</li><li><strong>Each file describes itself</strong> in its <code>&lt;head&gt;</code>: <code>&lt;title&gt;</code>, a <code>mockup:section</code> meta tag, and <code>mockup:shipped</code> naming the screenshot test references once the screen ships. The check script and the site gallery read these tags; there is no separate index to keep in step.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>English only; French copy is checked in the apps.</li><li>Light and dark from one file: mockups use the theme roles (<code>--cp-primary</code>, <code>--cp-surface</code>...), never a palette step that stays the same in both themes. <code>shared/mockup-theme.js</code> keeps one light or dark choice for every mockup, apart from the docs site&#39;s own theme, and falls back to the system setting. (Changed on 27 October 2026 at the owner&#39;s request; mockups were light only before.)</li><li>No network: no <code>fetch</code>, no scripts or styles from outside the repo except the brand fonts.</li><li>Real elements (<code>&lt;button&gt;</code>, <code>&lt;a&gt;</code>, labels), a <code>data-component</code> attribute naming the design-system component, and <code>id</code>s in glossary terms for the regions an issue would name.</li><li>Rendered PNGs are uploaded by CI for review, never committed, because renders differ between machines.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The canvas&#39;s 42 artboards are converted once, section by section, into <code>agreed/phone/</code>. Until that lands, the canvas still holds the existing screens.</li><li>Once a screen ships, screenshot tests become its truth: Roborazzi on Android and swift-snapshot-testing on a pinned iOS simulator in CI. Its agreed mockup is kept, frozen, with <code>mockup:shipped</code> pointing at the references, and only changes when the screen is redesigned through a new draft.</li><li>Canvas comments and free placement are lost; PR comments and the site&#39;s gallery replace them.</li></ul>`,9)])])}const u=s(o,[["render",r]]);export{m as __pageData,u as default};
